(()=>{const root=document.documentElement,themeButton=document.querySelector('#theme');if(localStorage.getItem('finance-theme')==='dark')root.classList.add('dark');const setIcon=()=>{const icon=themeButton?.querySelector('i');if(icon)icon.className=root.classList.contains('dark')?'fa-solid fa-sun':'fa-solid fa-moon'};setIcon();themeButton?.addEventListener('click',()=>{localStorage.setItem('finance-theme',root.classList.contains('dark')?'dark':'light');setIcon()});Chart.defaults.font.family='Inter, system-ui, sans-serif';Chart.defaults.color=getComputedStyle(root).getPropertyValue('--muted').trim();Chart.defaults.borderColor='rgba(120,130,160,.12)';const reveal=container=>container.querySelectorAll?.('.cardx').forEach((card,index)=>{card.style.opacity='0';card.style.transform='translateY(12px)';setTimeout(()=>{card.style.transitionDelay=`${Math.min(index,8)*35}ms`;card.style.opacity='1';card.style.transform='translateY(0)'},20)});const content=document.querySelector('#content');if(content){new MutationObserver(()=>reveal(content)).observe(content,{childList:true});reveal(content)}document.addEventListener('pointerdown',event=>{const button=event.target.closest('.btn,.icon-btn,.fab,nav button');if(!button)return;button.style.transform='scale(.96)';setTimeout(()=>button.style.transform='',160)},{passive:true})})();
